class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
        def go(lo, hi):
            if lo > hi: return None
            m = (lo + hi) // 2
            return TreeNode(nums[m], go(lo, m - 1), go(m + 1, hi))
        return go(0, len(nums) - 1)

